use std::ffi::OsString;
use yamantaka_storage::Database;
pub(super) fn seed(db: &Database, args: &[OsString]) -> Result<(), Box<dyn std::error::Error>> {
    db.execute_batch("INSERT INTO tags(id,name,normalized_name,color,created_at,updated_at) VALUES('legacy-recovery-tag','Imported references','imported references','violet','',''); INSERT INTO document_tags(document_id,tag_id) VALUES('demo-0','legacy-recovery-tag'); INSERT INTO collections(id,name,normalized_name,created_at,updated_at) VALUES('legacy-recovery-collection','Imported sources','imported sources','',''); INSERT INTO collection_documents(collection_id,document_id,added_at) VALUES('legacy-recovery-collection','demo-0','2026-10-30'); INSERT INTO workspaces(id,name,active_tab_id,split_json,created_at,updated_at) VALUES('legacy-recovery-workspace','Recovery desk','legacy-tab-0',' {\"enabled\":true,\"secondaryTabId\":\"legacy-tab-0\",\"vendor\":7} ','','2026-10-30'); INSERT INTO workspace_tabs(id,workspace_id,document_id,sort_order,is_pinned,page_index,zoom_level,page_layout,reading_mode,scroll_offset,queue_status,next_action) VALUES('legacy-tab-0','legacy-recovery-workspace','demo-0',0,1,0,1.7,'facing','book',31,'inReview','Compare sources'),('legacy-tab-1','legacy-recovery-workspace','demo-1',1,0,0,1,'single','document',0,'pending',NULL);")?;
    let receipts = r#" {"a":{"kind":"removeTag","documentId":"demo-0","tagId":"legacy-recovery-tag","changed":true},"b":{"kind":"removeCollection","documentId":"demo-0","collectionId":"legacy-recovery-collection","changed":true},"c":{"kind":"removeQueue","documentId":"demo-0","workspaceId":"legacy-recovery-workspace","changed":true},"d":{"kind":"restoreProgress","documentId":"demo-0","pageIndex":1,"pageCount":2,"viewMode":"book","theme":"sepia"},"e":{"kind":"restoreFavorite","documentId":"demo-0","value":true},"f":{"kind":"restoreFavorite","documentId":"demo-1","value":true},"g":{"kind":"removeTag","documentId":"absent-skipped","tagId":"legacy-recovery-tag","changed":false}} "#;
    db.execute_batch(&format!("UPDATE operation_journal SET undo_json='{}',completed_items=2 WHERE id='inherited-1-rollback'",receipts.replace('\'',"''")))?;
    if args.iter().any(|arg| arg == "--inherited-recovery-fail") {
        db.execute_batch("CREATE TRIGGER reject_inherited_delete BEFORE DELETE ON document_tags WHEN OLD.document_id='demo-0' BEGIN SELECT RAISE(ABORT,'synthetic inherited recovery failure'); END;")?;
    }
    Ok(())
}
